import os
import importlib.util
TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
format_phone = target.format_phone


def test_valid_10_digits():
    assert format_phone("1234567890") == "(123) 456-7890"


def test_valid_10_digits_2():
    assert format_phone("9876543210") == "(987) 654-3210"


def test_with_spaces_raises_value_error():
    try:
        format_phone("123 456 7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_with_dashes_raises_value_error():
    try:
        format_phone("123-456-7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_with_country_code_raises_value_error():
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_missing_digits_raises_value_error():
    try:
        format_phone("1234567")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_non_string_raises_type_error():
    try:
        format_phone(1234567890)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_empty_string_raises_value_error():
    try:
        format_phone("")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_with_parentheses_raises_value_error():
    try:
        format_phone("(123)4567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_11_digits_raises_value_error():
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_all_zeros():
    assert format_phone("0000000000") == "(000) 000-0000"


def test_format_structure():
    result = format_phone("5551234567")
    assert result == "(555) 123-4567"

