from typing import Iterable, List


def _validate_tax_rate(tax_rate: float) -> float:
    if not isinstance(tax_rate, (int, float)):
        raise TypeError("tax_rate must be numeric")
    if tax_rate < 0:
        raise ValueError("tax_rate must be non-negative")
