bucket_by_length = target.bucket_by_length


def test_basic_grouping():
    """Multiple words of the same length should all be in the bucket."""
    result = bucket_by_length(["a", "b", "hi"])
    assert result == {1: ["a", "b"], 2: ["hi"]}


def test_single_word():
    result = bucket_by_length(["hello"])
    assert result == {5: ["hello"]}


def test_empty_list():
    result = bucket_by_length([])
    assert result == {}


def test_empty_strings():
    """Empty strings are allowed and belong to bucket 0."""
    result = bucket_by_length(["", "a"])
    assert result == {0: [""], 1: ["a"]}


def test_preserves_order():
    """Input order within each bucket should be preserved."""
    result = bucket_by_length(["cat", "dog", "bat", "hi", "bye"])
    assert result == {3: ["cat", "dog", "bat"], 2: ["hi", "bye"]}


def test_multiple_lengths():
    result = bucket_by_length(["a", "bb", "ccc"])
    assert result == {1: ["a"], 2: ["bb"], 3: ["ccc"]}


def test_many_same_length():
    """Many words of same length - all should appear in bucket."""
    result = bucket_by_length(["red", "hot", "dog", "cat"])
    assert result == {3: ["red", "hot", "dog", "cat"]}


def test_non_list_raises_type_error():
    try:
        bucket_by_length(("a", "b"))
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_non_string_in_list_raises_type_error():
    try:
        bucket_by_length(["a", 123])
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_none_raises_type_error():
    try:
        bucket_by_length(None)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_mixed_lengths():
    result = bucket_by_length(["x", "yy", "zzz", "wwwww"])
    assert result == {1: ["x"], 2: ["yy"], 3: ["zzz"], 5: ["wwwww"]}


def test_duplicated_words():
    result = bucket_by_length(["a", "a", "b"])
    assert result == {1: ["a", "a", "b"]}


def test_two_words_same_length():
    """Two words of same length should both appear."""
    result = bucket_by_length(["hi", "hello"])
    assert result == {2: ["hi"], 5: ["hello"]}


def test_three_words_same_length():
    """Three words of same length - all should appear."""
    result = bucket_by_length(["hi", "no", "go"])
    assert result == {2: ["hi", "no", "go"]}

